use std::sync::{Arc, Mutex, atomic::{AtomicBool, Ordering}};
use std::collections::VecDeque;
use std::thread;
use std::time::Duration;

#[derive(Debug, Clone)]
pub struct Payment {
    pub id: u64,
    pub from: String,
    pub to: String,
    pub amount: u64,
    pub priority: u8,
}

#[derive(Debug, Clone)]
pub struct ProcessedPayment {
    pub payment: Payment,
    pub sequence_number: u64,
}

pub struct PaymentQueue {
    pending: Mutex<VecDeque<Payment>>,
    processing: Mutex<Vec<ProcessedPayment>>,
    sequence_counter: Mutex<u64>,
    shutting_down: AtomicBool,
    drain_complete: AtomicBool,
}

impl PaymentQueue {
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            pending: Mutex::new(VecDeque::new()),
            processing: Mutex::new(Vec::new()),
            sequence_counter: Mutex::new(0),
            shutting_down: AtomicBool::new(false),
            drain_complete: AtomicBool::new(false),
        })
    }

    pub fn submit_payment(&self, payment: Payment) -> Result<(), &'static str> {
        if self.shutting_down.load(Ordering::Acquire) {
            return Err("System is shutting down, no new payments accepted");
        }
        let mut queue = self.pending.lock().unwrap();
        queue.push_back(payment);
        Ok(())
    }

    /// During graceful shutdown, reorder remaining payments by priority
    /// to ensure high-priority payments settle first
    pub fn initiate_graceful_shutdown(&self) {
        self.shutting_down.store(true, Ordering::Release);

        // Allow in-flight submissions to complete
        thread::sleep(Duration::from_millis(10));

        // Reorder remaining queue by priority for fair settlement
        self.reorder_for_settlement();

        // Process remaining payments
        self.drain_remaining();

        self.drain_complete.store(true, Ordering::Release);
    }

    fn reorder_for_settlement(&self) {
        let mut queue = self.pending.lock().unwrap();
        let mut payments: Vec<Payment> = queue.drain(..).collect();

        // Sort by priority descending, then by amount descending for same priority
        // This ensures high-value, high-priority payments settle first
        payments.sort_by(|a, b| {
            b.priority.cmp(&a.priority)
                .then_with(|| b.amount.cmp(&a.amount))
        });

        for p in payments {
            queue.push_back(p);
        }
    }

    fn drain_remaining(&self) {
        let mut queue = self.pending.lock().unwrap();
        let mut processed = self.processing.lock().unwrap();
        let mut counter = self.sequence_counter.lock().unwrap();

        while let Some(payment) = queue.pop_front() {
            *counter += 1;
            processed.push(ProcessedPayment {
                payment,
                sequence_number: *counter,
            });
        }
    }

    pub fn process_next(&self) -> Option<ProcessedPayment> {
        if self.drain_complete.load(Ordering::Acquire) {
            return None;
        }

        let mut queue = self.pending.lock().unwrap();
        let mut counter = self.sequence_counter.lock().unwrap();

        if let Some(payment) = queue.pop_front() {
            *counter += 1;
            let processed = ProcessedPayment {
                payment,
                sequence_number: *counter,
            };
            let mut processing = self.processing.lock().unwrap();
            processing.push(processed.clone());
            Some(processed)
        } else {
            None
        }
    }

    pub fn get_settlement_order(&self) -> Vec<ProcessedPayment> {
        self.processing.lock().unwrap().clone()
    }
}

/// Operator-triggered shutdown that processes remaining payments
/// in priority order for orderly settlement
pub fn operator_shutdown(queue: &Arc<PaymentQueue>) {
    queue.initiate_graceful_shutdown();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_graceful_shutdown_settles_by_priority() {
        let queue = PaymentQueue::new();

        // Simulate normal operation - payments arrive in order
        queue.submit_payment(Payment {
            id: 1, from: "alice".into(), to: "bob".into(),
            amount: 100, priority: 1,
        }).unwrap();
        queue.submit_payment(Payment {
            id: 2, from: "charlie".into(), to: "dave".into(),
            amount: 5000, priority: 5,
        }).unwrap();
        queue.submit_payment(Payment {
            id: 3, from: "eve".into(), to: "frank".into(),
            amount: 200, priority: 1,
        }).unwrap();

        // Operator initiates shutdown
        operator_shutdown(&queue);

        let settled = queue.get_settlement_order();
        // High priority payment (id=2) should settle first
        assert_eq!(settled[0].payment.id, 2);
        assert_eq!(settled[0].sequence_number, 1);
    }
}
